import React, { useState, useEffect } from 'react'
import { AuthProvider, useAuth } from '../../../contexts/AuthContext'
import { Toaster } from 'react-hot-toast'
import LoginButton from '../auth/LoginButton'
import UserProfile from '../auth/UserProfile'
import ProfileSideMenu from '../auth/ProfileSideMenu'
import VenueSelector from '../venues/VenueSelector'
import SettingsModal from '../settings/SettingsModal'
import { getAllVenuesSorted, type Venue } from '../../../data/venues'
import { getTotalAttendeesCount, getAllAttendees, getAllVenueAttendanceCounts } from '../../../services/venueService'
import { getVenueChecklist, calculateChecklistProgress } from '../../../services/checklistService'
import { getGlobalComments, getUserLatestComment, type Comment } from '../../../services/commentService'
import { CommentForm } from '../../common/CommentForm'
import { Countdown } from '../../common/Countdown'
import { DEFAULT_GRADIENT } from '../../../data/venues/gradients'
import { getPrefectureGradient } from '../../../data/prefectureColors'
import { Link } from 'gatsby'
import { MapPin, Users, Calendar, ArrowRight, Clock, Home, Building2 } from 'lucide-react'

const ReolMapContent: React.FC = () => {
  const { user, profile, loading, createProfileInSupabase } = useAuth()
  const [activeTab, setActiveTab] = useState<'venues' | 'overview'>('overview')
  const [isSettingsOpen, setIsSettingsOpen] = useState(false)
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false)
  const [totalAttendees, setTotalAttendees] = useState<number>(0)
  const [selectedVenuesFromDB, setSelectedVenuesFromDB] = useState<string[]>([])
  const [isLoadingVenues, setIsLoadingVenues] = useState(false)
  const [showAllAttendeesModal, setShowAllAttendeesModal] = useState(false)
  const [allAttendees, setAllAttendees] = useState<any[]>([])
  const [checklistProgress, setChecklistProgress] = useState<{ [venueId: string]: number }>({})
  const [venueAttendanceCounts, setVenueAttendanceCounts] = useState<{ [venueId: string]: number }>({})
  const [showVenueSelector, setShowVenueSelector] = useState(false)
  const [globalComments, setGlobalComments] = useState<{ [userId: string]: Comment }>({})
  
  const venues = getAllVenuesSorted()
  const upcomingVenues = venues.slice(0, 5) // 直近5会場

  // モーダル表示中は背後のスクロールを無効化
  useEffect(() => {
    if (showAllAttendeesModal || showVenueSelector || isSettingsOpen || isProfileMenuOpen) {
      document.body.style.overflow = 'hidden'
    } else {
      document.body.style.overflow = 'unset'
    }
    
    // クリーンアップ: コンポーネントがアンマウントされるときにリセット
    return () => {
      document.body.style.overflow = 'unset'
    }
  }, [showAllAttendeesModal, showVenueSelector, isSettingsOpen, isProfileMenuOpen])

  // 会場タイプを判定する関数
  const getVenueType = (venueName: string, capacity: number) => {
    // 横浜ベイホールは例外的にライブハウス扱い
    if (venueName.includes('BAYHALL') || venueName.includes('BayHall') || venueName.includes('ベイホール')) {
      return 'livehouse'
    }
    // キャパシティが大きい、または「ホール」「劇場」「公会堂」などを含む場合はホール
    if (capacity >= 800 || venueName.includes('ホール') || venueName.includes('劇場') || 
        venueName.includes('公会堂') || venueName.includes('会館') || venueName.includes('会議場') ||
        venueName.includes('CUBE') || venueName.includes('アリーナ')) {
      return 'hall'
    }
    return 'livehouse'
  }

  // 会場のグラデーション背景を取得する関数
  const getVenueGradient = (venue: Venue): string => {
    // 1. 会場個別のグラデーション設定があればそれを優先
    if (venue.gradient) {
      return `linear-gradient(135deg, ${venue.gradient.from}, ${venue.gradient.to})`
    }
    // 2. 都道府県カラーを適用
    const prefectureGradient = getPrefectureGradient(venue.location.prefecture)
    if (prefectureGradient !== 'rgba(216, 217, 195, 0.9)') {
      return prefectureGradient
    }
    // 3. デフォルトは単色
    return DEFAULT_GRADIENT.from
  }

  // ログインユーザーの会場選択をSupabaseから取得
  useEffect(() => {
    const loadUserVenues = async () => {
      if (user) {
        setIsLoadingVenues(true)
        try {
          const { supabase } = await import('../../../lib/supabase')
          const { data, error } = await supabase
            .from('venue_attendances')
            .select('venue_id')
            .eq('user_id', user.id)

          if (error) {
            console.error('Error loading user venues:', error)
          } else if (data) {
            const venueIds = data.map(item => item.venue_id)
            setSelectedVenuesFromDB(venueIds)
            // ローカルストレージも更新
            if (typeof window !== 'undefined') {
              localStorage.setItem('reolmap_selected_venues', JSON.stringify(venueIds))
            }
          }
        } catch (error) {
          console.error('Error in loadUserVenues:', error)
        } finally {
          setIsLoadingVenues(false)
        }
      } else {
        // 未ログイン時はデータをクリア
        setSelectedVenuesFromDB([])
        setIsLoadingVenues(false)
        // ローカルストレージもクリア
        if (typeof window !== 'undefined') {
          localStorage.removeItem('reolmap_selected_venues')
        }
      }
    }
    loadUserVenues()
  }, [user])

  // 全体の参加表明者数を取得
  useEffect(() => {
    const fetchTotalAttendees = async () => {
      const count = await getTotalAttendeesCount()
      setTotalAttendees(count)
    }
    fetchTotalAttendees()
  }, [])

  // モーダルが開いたときに全参加者データを取得
  useEffect(() => {
    const fetchAllAttendees = async () => {
      if (showAllAttendeesModal) {
        const attendees = await getAllAttendees()
        setAllAttendees(attendees)
      }
    }
    fetchAllAttendees()
  }, [showAllAttendeesModal])

  // チェックリスト進捗率を取得
  useEffect(() => {
    const loadChecklistProgress = async () => {
      if (user && selectedVenuesFromDB.length > 0) {
        const progress: { [venueId: string]: number } = {}
        await Promise.all(
          selectedVenuesFromDB.map(async (venueId) => {
            const checklist = await getVenueChecklist(user.id, venueId)
            progress[venueId] = calculateChecklistProgress(checklist)
          })
        )
        setChecklistProgress(progress)
      } else {
        setChecklistProgress({})
      }
    }
    loadChecklistProgress()
  }, [user, selectedVenuesFromDB])

  // 全会場の参加人数を取得
  useEffect(() => {
    const loadVenueAttendanceCounts = async () => {
      const venueIds = venues.map(v => v.id)
      const counts = await getAllVenueAttendanceCounts(venueIds)
      setVenueAttendanceCounts(counts)
    }
    loadVenueAttendanceCounts()
  }, [])

  // 全体コメントを取得
  useEffect(() => {
    const loadGlobalComments = async () => {
      const comments = await getGlobalComments()
      // ユーザーごとの最新コメントをマップに格納
      const commentsMap: { [userId: string]: Comment } = {}
      comments.forEach(comment => {
        if (!commentsMap[comment.user_id]) {
          commentsMap[comment.user_id] = comment
        }
      })
      setGlobalComments(commentsMap)
    }
    loadGlobalComments()
  }, [])

  // コメント投稿後に再取得
  const handleCommentPosted = async () => {
    const comments = await getGlobalComments()
    const commentsMap: { [userId: string]: Comment } = {}
    comments.forEach(comment => {
      if (!commentsMap[comment.user_id]) {
        commentsMap[comment.user_id] = comment
      }
    })
    setGlobalComments(commentsMap)
  }

  // 選択した会場数を取得（ログイン時はSupabaseから、未ログイン時はローカルストレージから）
  const getSelectedVenuesCount = () => {
    if (user) {
      // ログイン時はSupabaseから取得したデータを使用
      return selectedVenuesFromDB.length
    }
    // 未ログイン時はローカルストレージから取得
    if (typeof window === 'undefined') return 0
    const saved = localStorage.getItem('reolmap_selected_venues')
    if (saved) {
      try {
        return JSON.parse(saved).length
      } catch (error) {
        return 0
      }
    }
    return 0
  }

  // 選択した会場IDリストを取得（ログイン時はSupabaseから、未ログイン時はローカルストレージから）
  const getSelectedVenues = (): string[] => {
    if (user) {
      // ログイン時はSupabaseから取得したデータを使用
      return selectedVenuesFromDB
    }
    // 未ログイン時はローカルストレージから取得
    if (typeof window === 'undefined') return []
    const saved = localStorage.getItem('reolmap_selected_venues')
    if (saved) {
      try {
        return JSON.parse(saved)
      } catch (error) {
        return []
      }
    }
    return []
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-500"></div>
      </div>
    )
  }

  // コンテンツは常に表示し、ヘッダーでログイン状態を管理

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return {
      month: date.getMonth() + 1,
      day: date.getDate(),
      dayOfWeek: ['日', '月', '火', '水', '木', '金', '土'][date.getDay()],
    }
  }

  const Header = () => (
    <header 
      className="shadow-sm border-b border-gray-200 dark:border-gray-700"
      style={{
        backgroundColor: '#977c30'
      }}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-20">
          <div className="flex items-center">
            <div>
              <h1>
                <Link 
                  to="/bijigaku-navi" 
                  className="text-2xl font-bold block" 
                  style={{ 
                    color: '#ffffff',
                    textShadow: '2px 2px 3px rgba(0, 0, 0, 0.3)',
                    fontFamily: '"HiraMinProN-W6", "Yu Mincho", "YuMincho", "Hiragino Mincho ProN", "MS PMincho", serif',
                    fontWeight: 700,
                    letterSpacing: '0.05em'
                  }}
                >
                  美辞学ナビ
                </Link>
              </h1>
              <p 
                className="text-xs mt-0.5"
                style={{
                  color: 'rgba(255, 255, 255, 0.85)',
                  letterSpacing: '0.08em',
                  fontFamily: '"Helvetica Neue", Arial, sans-serif'
                }}
              >
                Reol Oneman Live 2026 Tour Navi
              </p>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            {/* Development buttons are hidden
            {process.env.NODE_ENV === 'development' && (
              <div className="flex items-center space-x-2">
                <button
                  onClick={async () => {
                    try
                      const { supabase } = await import('../../../lib/supabase')
                      if (supabase) {
                        console.log('=== Database Check ===')
                        
                        // profilesテーブルの確認
                        const { data: profiles, error: profileError } = await supabase
                          .from('profiles')
                          .select('*')
                          .limit(1)
                        console.log('Profiles table:', { data: profiles, error: profileError })
                        
                        // venue_attendancesテーブルの確認
                        const { data: attendances, error: attendanceError } = await supabase
                          .from('venue_attendances')
                          .select('*')
                          .limit(1)
                        console.log('Venue_attendances table:', { data: attendances, error: attendanceError })
                        
                        console.log('=== End Database Check ===')
                      }
                    } catch (error) {
                      console.error('Database check failed:', error)
                    }
                  }}
                  className="px-3 py-1 text-xs bg-green-500 text-white rounded hover:bg-green-600"
                >
                  Check DB
                </button>
                {user && (
                  <button
                    onClick={() => createProfileInSupabase && createProfileInSupabase()}
                    className="px-3 py-1 text-xs bg-orange-500 text-white rounded hover:bg-orange-600"
                  >
                    Create Profile
                  </button>
                )}
              </div>
            )}
            */}
            {user ? (
              <UserProfile compact onProfileClick={() => setIsProfileMenuOpen(true)} />
            ) : (
              <div className="flex items-center space-x-3">
                <LoginButton compact />
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  )

  const OverviewTab = () => {
    // ユーザー表示名の取得（優先順位: full_name > display_name > username > メールアドレスのローカル部分 > null（未ログイン））
    const getUserDisplayName = () => {
      if (profile?.full_name) return profile.full_name
      if (profile?.display_name) return profile.display_name
      if (profile?.username) return profile.username
      if (user?.email) return user.email.split('@')[0]
      return null // 未ログイン
    }

    return (
      <div className="space-y-6">
        <div className="text-center space-y-4">
          <p className="text-lg text-gray-600 dark:text-gray-300">
            各会場の情報をチェック！
          </p>
          
          {/* カウントダウン */}
          <div className="flex justify-center gap-4 w-full px-2 mb-6">
            <div className="flex gap-4" style={{ width: 'calc(256px * 2 + 1rem + 4px)' }}>
              <Countdown />
            </div>
          </div>

          {/* 統計カード - 横一列レイアウト */}
          <div className="flex justify-center gap-4 w-full px-4">
            {/* 総参加表明者カード - クリック可能 */}
            <div 
              className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6 text-center w-64 cursor-pointer hover:shadow-xl hover:scale-105 transition-all duration-200"
              onClick={() => setShowAllAttendeesModal(true)}
            >
              <div className="flex flex-col items-center gap-2">
                <span className="text-4xl">👥</span>
                <div className="text-gray-600 dark:text-gray-400 text-sm whitespace-nowrap">総参加表明者</div>
                <div className="text-3xl font-bold text-orange-600 dark:text-orange-400 whitespace-nowrap">
                  {totalAttendees}人
                </div>
                <div className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                  👆 タップして一覧を見る
                </div>
              </div>
            </div>

            {/* あなたの参加カード - クリック可能 */}
            <div 
              className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6 text-center w-64 cursor-pointer hover:shadow-xl hover:scale-105 transition-all duration-200"
              onClick={() => setShowVenueSelector(true)}
            >
              <div className="flex flex-col items-center gap-2">
                <span className="text-4xl">🏠</span>
                <div className="text-gray-600 dark:text-gray-400 text-sm whitespace-nowrap">
                  {getUserDisplayName() ? `${getUserDisplayName()}さんの参加` : 'あなたの参加'}
                </div>
                <div className="text-3xl font-bold text-emerald-600 dark:text-emerald-400 whitespace-nowrap">
                  {getSelectedVenuesCount()}会場
                </div>
                <div className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                  👆 タップして編集
                </div>
              </div>
            </div>
          </div>

          {/* セットリスト予想リンク */}
          <div className="flex justify-center w-full px-4 mt-6">
            <div className="flex gap-4" style={{ width: 'calc(256px * 2 + 1rem)' }}>
              <Link
                to="/bijigaku-navi/setlist-prediction/"
                className="bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-700 text-purple-600 dark:text-purple-400 rounded-lg shadow-md p-6 hover:shadow-xl hover:scale-105 transition-all duration-200 flex-1 flex items-center gap-3"
              >
                <span className="text-2xl">🎵</span>
                <div className="text-left">
                  <div className="font-bold text-lg">セットリスト予想</div>
                  <div className="text-sm opacity-90">美辞学ツアーで聴きたい曲に投票！</div>
                </div>
              </Link>
            </div>
          </div>
        </div>

        {/* 参加表明会場 */}
        {user && getSelectedVenuesCount() > 0 && (
        <div className="rounded-lg shadow-sm border border-gray-200 dark:border-gray-700" style={{ backgroundColor: 'rgba(216, 217, 195, 0.9)' }}>
          <div className="p-4 border-b border-gray-200 dark:border-gray-700">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
              {profile?.full_name || profile?.username || 'あなた'}さんの参加会場
            </h2>
          </div>
          <div className="p-4 space-y-3">
            {getSelectedVenues()
              .map((venueId: string) => venues.find((v: any) => v.id === venueId))
              .filter((venue: any) => venue != null)
              .sort((a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime())
              .map((venue: any) => {
              const dateInfo = formatDate(venue.date)
              
              return (
                <Link
                  key={venue.id}
                  to={`/bijigaku-navi/venue/${venue.id}/`}
                  className="block p-3 rounded-lg transition-colors border border-gray-100 dark:border-gray-600"
                  style={{ background: getVenueGradient(venue) }}
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <h3 className="font-medium text-white" style={{ textShadow: '1px 1px 2px rgba(0, 0, 0, 0.5)' }}>
                        {venue.name}
                      </h3>
                      <div className="space-y-1 mt-1">
                        <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5 text-sm text-white" style={{ textShadow: '1px 1px 2px rgba(0, 0, 0, 0.5)' }}>
                          <span className="flex items-center gap-1 whitespace-nowrap">
                            <MapPin className="h-3 w-3" />
                            {venue.location.prefecture}
                          </span>
                          <span className="whitespace-nowrap">
                            {dateInfo.month}/{dateInfo.day}({dateInfo.dayOfWeek})
                          </span>
                          <span className="whitespace-nowrap">
                            キャパ {venue.capacity ? venue.capacity.toLocaleString() : '不明'}人
                          </span>
                          {venueAttendanceCounts[venue.id] !== undefined && (
                            <span className="text-yellow-200 font-medium whitespace-nowrap">
                              👥 {venueAttendanceCounts[venue.id]}人
                            </span>
                          )}
                        </div>
                        <div className="flex items-center gap-1 text-sm text-white" style={{ textShadow: '1px 1px 2px rgba(0, 0, 0, 0.5)' }}>
                          <Clock className="h-3 w-3" />
                          開場{venue.times.open} / 開演{venue.times.start}
                        </div>
                        {checklistProgress[venue.id] !== undefined && (
                          <div className="flex items-center gap-1 text-sm text-white font-medium">
                            <span>📋</span>
                            チェックリスト {checklistProgress[venue.id]}%
                          </div>
                        )}
                      </div>
                    </div>
                    <ArrowRight className="h-4 w-4 text-gray-300" />
                  </div>
                </Link>
              )
            })}
          </div>
        </div>
      )}

      {/* 全会場一覧 / その他の会場一覧 */}
      {(() => {
        const otherVenues = venues.filter((venue: any) => {
          // ログイン済みの場合は参加表明済みの会場を除外
          if (user) {
            return !getSelectedVenues().includes(venue.id)
          }
          // ゲストの場合は全件表示
          return true
        })
        
        // その他の会場が0件の場合は非表示
        if (otherVenues.length === 0) {
          return null
        }
        
        return (
          <div className="rounded-lg shadow-sm border border-gray-200 dark:border-gray-700" style={{ backgroundColor: 'rgba(216, 217, 195, 0.9)' }}>
            <div className="p-4 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                {user ? 'その他の会場一覧' : '会場一覧'}
              </h2>
            </div>
            <div className="p-4 space-y-3">
              {otherVenues.map((venue: any) => {
            const dateInfo = formatDate(venue.date)
            const isAttending = getSelectedVenues().includes(venue.id)
            const venueType = getVenueType(venue.name, venue.capacity)
            
            return (
              <Link
                key={venue.id}
                to={`/bijigaku-navi/venue/${venue.id}/`}
                className="block p-3 rounded-lg transition-colors border border-gray-100 dark:border-gray-600"
                style={{ background: getVenueGradient(venue) }}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    {venueType === 'hall' ? (
                      <Building2 className="h-5 w-5 text-emerald-400 flex-shrink-0" style={{ filter: 'drop-shadow(1px 1px 1px rgba(0, 0, 0, 0.5))' }} />
                    ) : (
                      <Home className="h-5 w-5 text-orange-400 flex-shrink-0" style={{ filter: 'drop-shadow(1px 1px 1px rgba(0, 0, 0, 0.5))' }} />
                    )}
                    <div>
                      <h3 className="font-medium text-white" style={{ textShadow: '1px 1px 2px rgba(0, 0, 0, 0.5)' }}>
                        {venue.name}
                      </h3>
                      <div className="space-y-1 mt-1">
                        <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5 text-sm text-white" style={{ textShadow: '1px 1px 2px rgba(0, 0, 0, 0.5)' }}>
                          <span className="flex items-center gap-1 whitespace-nowrap">
                            <MapPin className="h-3 w-3" />
                            {venue.location.prefecture}
                          </span>
                          <span className="whitespace-nowrap">
                            {dateInfo.month}/{dateInfo.day}({dateInfo.dayOfWeek})
                          </span>
                          <span className="whitespace-nowrap">
                            キャパ {venue.capacity.toLocaleString()}人
                          </span>
                          {venueAttendanceCounts[venue.id] !== undefined && (
                            <span className="text-yellow-200 font-medium whitespace-nowrap">
                              👥 {venueAttendanceCounts[venue.id]}人
                            </span>
                          )}
                        </div>
                        <div className="flex items-center gap-1 text-sm text-white" style={{ textShadow: '1px 1px 2px rgba(0, 0, 0, 0.5)' }}>
                          <Clock className="h-3 w-3" />
                          開場{venue.times.open} / 開演{venue.times.start}
                        </div>
                      </div>
                    </div>
                  </div>
                  <ArrowRight className="h-4 w-4 text-gray-300" />
                </div>
              </Link>
            )
          })}
            </div>
          </div>
        )
      })()}
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-transparent m-0 p-0">
      <Header />
      
      <div className="max-w-4xl mx-auto p-4 space-y-6">
        {/* コンテンツエリア */}
        <OverviewTab />
      </div>
        
      {/* プロフィールサイドメニュー */}
      <ProfileSideMenu 
        isOpen={isProfileMenuOpen}
        onClose={() => setIsProfileMenuOpen(false)}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />
      
      {/* 設定モーダル */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
      />

      {/* 全参加者モーダル */}
      {showAllAttendeesModal && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4"
          onClick={() => setShowAllAttendeesModal(false)}
        >
          <div 
            className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-2xl w-full max-h-[80vh] overflow-hidden flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            {/* ヘッダー */}
            <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700 flex-shrink-0">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                総参加表明者 ({totalAttendees}人)
              </h2>
              <button
                onClick={() => setShowAllAttendeesModal(false)}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <span className="text-2xl">×</span>
              </button>
            </div>

            {/* コメント入力フォーム */}
            <div className="px-6 pt-4 pb-2 border-b border-gray-200 dark:border-gray-700 flex-shrink-0">
              <div className="mb-2">
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  💬 ツアー全体についてのコメント
                </p>
              </div>
              <CommentForm 
                venueId={null} 
                onCommentPosted={handleCommentPosted}
                placeholder="ツアーについてコメントを投稿..."
              />
            </div>

            {/* 参加者リスト */}
            <div className="overflow-y-auto flex-1 p-6">
              {allAttendees.length === 0 ? (
                <p className="text-center text-gray-500 dark:text-gray-400">
                  参加者データを読み込んでいます...
                </p>
              ) : (
                <div className="space-y-3">
                  {allAttendees.map((attendee, index) => {
                    const displayName = attendee.username || attendee.full_name || '名無し'
                    const userId = attendee.user_id || attendee.id
                    const link = `https://x.com/${userId}`
                    const comment = globalComments[userId]
                    
                    return (
                      <div 
                        key={userId || index}
                        className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors"
                      >
                        <div className="flex items-center justify-between">
                          <div>
                            <div className="font-medium text-base text-gray-900 dark:text-white">
                              {displayName}
                            </div>
                            <div className="text-sm text-gray-500 dark:text-gray-400">
                              ID: {userId}
                            </div>
                          </div>
                          {userId && (
                            <a
                              href={link}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="text-blue-500 hover:text-blue-600 dark:text-blue-400 dark:hover:text-blue-300 text-base"
                            >
                              X →
                            </a>
                          )}
                        </div>
                        
                        {/* コメント吹き出し */}
                        {comment && (
                          <div className="mt-3 bg-white dark:bg-gray-600 rounded-lg p-3 relative">
                            <div className="absolute -top-2 left-4 w-4 h-4 bg-white dark:bg-gray-600 transform rotate-45"></div>
                            <div className="flex items-start justify-between gap-2">
                              <div className="flex-1">
                                <p className="text-base text-gray-700 dark:text-gray-200 relative z-10">
                                  {comment.content}
                                </p>
                                <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 relative z-10">
                                  {new Date(comment.created_at).toLocaleString('ja-JP', {
                                    year: 'numeric',
                                    month: '2-digit',
                                    day: '2-digit',
                                    hour: '2-digit',
                                    minute: '2-digit',
                                    timeZone: 'Asia/Tokyo'
                                  }).replace(/\//g, '-')}
                                </p>
                              </div>
                              {profile?.id === attendee.id && (
                                <button
                                  onClick={async () => {
                                    if (confirm('コメントを削除しますか？')) {
                                      const { deleteComment } = await import('../../../services/commentService')
                                      const success = await deleteComment(comment.id)
                                      if (success) {
                                        await handleCommentPosted()
                                        alert('コメントを削除しました')
                                      }
                                    }
                                  }}
                                  className="px-1.5 py-0.5 bg-red-500 hover:bg-red-600 text-white rounded text-xl font-bold relative z-10 flex-shrink-0 w-7 h-7 flex items-center justify-center leading-none"
                                  title="削除"
                                >
                                  <span className="block -mt-0.5">×</span>
                                </button>
                              )}
                            </div>
                          </div>
                        )}
                      </div>
                    )
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* 会場設定モーダル */}
      {showVenueSelector && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4"
          onClick={() => setShowVenueSelector(false)}
        >
          <div 
            className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-4xl w-full max-h-[90vh] overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            {/* ヘッダー */}
            <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                会場設定
              </h2>
              <button
                onClick={() => setShowVenueSelector(false)}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <span className="text-2xl">×</span>
              </button>
            </div>

            {/* 会場セレクター */}
            <div className="overflow-y-auto max-h-[calc(90vh-80px)] p-4">
              <VenueSelector />
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

// メインコンポーネント：AuthProviderでラップ
const ReolMapLayout: React.FC = () => {
  return (
    <AuthProvider>
      <ReolMapContent />
      <Toaster 
        position="top-right"
        toastOptions={{
          duration: 3000,
          style: {
            background: '#363636',
            color: '#fff',
          },
        }}
      />
    </AuthProvider>
  )
}

export default ReolMapLayout